package com.pharmacy.controller;
import com.pharmacy.enums.UserRole;import com.pharmacy.exception.GlobalExceptionHandler;import com.pharmacy.security.AuthenticatedUser;import com.pharmacy.service.CartService;import org.junit.jupiter.api.*;import org.springframework.http.MediaType;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import java.util.List;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class UserCartControllerTest {private CartService service;private MockMvc mvc;@BeforeEach void setup(){service=mock(CartService.class);mvc=MockMvcBuilders.standaloneSetup(new UserCartController(service)).setControllerAdvice(new GlobalExceptionHandler(org.mockito.Mockito.mock(com.pharmacy.observability.PharmacyBusinessMetrics.class))).build();AuthenticatedUser u=new AuthenticatedUser(7L,"u","U",UserRole.USER);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of()));}@AfterEach void tearDown(){SecurityContextHolder.clearContext();}@Test void getCart()throws Exception{mvc.perform(get("/api/user/cart")).andExpect(status().isOk());verify(service).getCart(7L);}@Test void add()throws Exception{mvc.perform(post("/api/user/cart/items").contentType(MediaType.APPLICATION_JSON).content("{\"medicineId\":1,\"quantity\":2}")).andExpect(status().isOk());verify(service).add(eq(7L),any());}@Test void remove()throws Exception{mvc.perform(delete("/api/user/cart/items/3")).andExpect(status().isOk());verify(service).remove(7L,3L);}}
